const T = DATA.tokens;
const PRIM_COLLECTION = 'Milo · Primitives';
const TOKEN_COLLECTION = 'Milo · Tokens';
const SECTION_NAME = 'Foundations · 配重片（插件生成，勿手改）';
const COMPONENTS_SECTION = 'Components · 配重片（插件生成，勿手改）';
const BENCHMARK_SECTION = 'Benchmark · P06（插件生成，勿手改）';
const STYLE_PREFIX = 'Milo/';
const report = { created: 0, updated: 0, removed: 0, warnings: [] };
const warn = (m) => { report.warnings.push(m); console.warn('[milo] ' + m); };

// ---------------------------------------------------------------- 工具
function rgba(hex) {
  const h = hex.replace('#', '');
  const c = (i) => parseInt(h.slice(i, i + 2), 16) / 255;
  return { r: c(0), g: c(2), b: c(4), a: h.length === 8 ? c(6) : 1 };
}
const cssName = (prefix, name) => 'var(--milo-' + prefix + name.replace(/\//g, '-') + ')';

async function collection(name, hidden) {
  const all = await figma.variables.getLocalVariableCollectionsAsync();
  let c = all.find((x) => x.name === name);
  if (!c) c = figma.variables.createVariableCollection(name);
  if (c.modes[0].name !== T.meta.mode) c.renameMode(c.modes[0].modeId, T.meta.mode);
  if (hidden) { try { c.hiddenFromPublishing = true; } catch (e) { /* 旧版本没有这个属性 */ } }
  return c;
}

// defs: [{ name, type, value, desc, scopes, css }]，value 可以是别名
async function upsertVariables(coll, defs) {
  const all = await figma.variables.getLocalVariablesAsync();
  const byName = new Map(all.filter((v) => v.variableCollectionId === coll.id).map((v) => [v.name, v]));
  const modeId = coll.modes[0].modeId;
  const out = {};
  for (const d of defs) {
    let v = byName.get(d.name);
    if (v && v.resolvedType !== d.type) { v.remove(); v = null; }
    if (!v) { v = figma.variables.createVariable(d.name, coll, d.type); report.created++; } else report.updated++;
    byName.delete(d.name);
    v.setValueForMode(modeId, d.value);
    v.description = d.desc || '';
    try { v.scopes = d.scopes; } catch (e) { warn('变量 ' + d.name + ' 的 scopes 设置失败：' + e.message); }
    try { v.setVariableCodeSyntax('WEB', d.css); } catch (e) { /* 可选 */ }
    out[d.name] = v;
  }
  for (const v of byName.values()) { v.remove(); report.removed++; }
  return out;
}

const boundPaint = (v, opacity) => figma.variables.setBoundVariableForPaint(opacity == null ? { type: 'SOLID', color: { r: 0, g: 0, b: 0 } } : { type: 'SOLID', color: { r: 0, g: 0, b: 0 }, opacity: opacity }, 'color', v);

// 字体：先试要求的字重，再试同族 Bold / Regular，最后退到 Inter
const fontCache = {};
async function font(family, style) {
  const key = family + '|' + style;
  if (fontCache[key]) return fontCache[key];
  const tries = [[family, style], [family, style === 'Black' ? 'Bold' : 'Regular'], ['Inter', style === 'Regular' ? 'Regular' : 'Bold'], ['Inter', 'Regular']];
  for (const [f, s] of tries) {
    try {
      await figma.loadFontAsync({ family: f, style: s });
      if (f !== family || s !== style) warn('字体 ' + family + ' ' + style + ' 不可用，暂用 ' + f + ' ' + s + '（装上该字体后重新运行插件即可）');
      fontCache[key] = { family: f, style: s };
      return fontCache[key];
    } catch (e) { /* 下一个 */ }
  }
  throw new Error('连 Inter Regular 都加载不了');
}

async function upsertStyle(kind, name) {
  const full = STYLE_PREFIX + name;
  const list = kind === 'text' ? await figma.getLocalTextStylesAsync() : kind === 'effect' ? await figma.getLocalEffectStylesAsync() : await figma.getLocalPaintStylesAsync();
  let s = list.find((x) => x.name === full);
  if (!s) { s = kind === 'text' ? figma.createTextStyle() : kind === 'effect' ? figma.createEffectStyle() : figma.createPaintStyle(); s.name = full; report.created++; } else report.updated++;
  return s;
}

// 仓库里删掉的样式，从 Figma 里也删掉（只删 Milo/ 前缀下的）
async function pruneStyles(kind, keep) {
  const list = kind === 'text' ? await figma.getLocalTextStylesAsync() : kind === 'effect' ? await figma.getLocalEffectStylesAsync() : await figma.getLocalPaintStylesAsync();
  for (const s of list) if (s.name.indexOf(STYLE_PREFIX) === 0 && keep.indexOf(s.name) < 0) { s.remove(); report.removed++; }
}

// ---------------------------------------------------------------- 排版小工具（说明分区、组件、标杆页共用）
function frame(name, dir, gap) {
  const f = figma.createFrame();
  f.name = name;
  f.layoutMode = dir;
  f.itemSpacing = gap;
  f.primaryAxisSizingMode = 'AUTO';
  f.counterAxisSizingMode = 'AUTO';
  f.fills = [];
  f.clipsContent = false;
  return f;
}
async function label(parent, chars, style, color, width) {
  const t = figma.createText();
  await t.setTextStyleIdAsync(style.id);
  t.characters = chars;
  t.fills = [boundPaint(color)];
  // 先定宽再设「自动高度」：resize() 会把文字改成固定尺寸
  if (width) { t.resize(width, Math.max(1, t.height)); t.textAutoResize = 'HEIGHT'; }
  parent.appendChild(t);
  return t;
}
function bindRadius(node, v) { for (const k of ['topLeftRadius', 'topRightRadius', 'bottomLeftRadius', 'bottomRightRadius']) node.setBoundVariable(k, v); }


/* Foundations：变量、样式、说明分区 */
// ---------------------------------------------------------------- 变量
async function importVariables() {
  const primColl = await collection(PRIM_COLLECTION, true);
  const prim = await upsertVariables(primColl, Object.keys(T.primitives.color).map((k) => ({
    name: 'color/' + k, type: 'COLOR', value: rgba(T.primitives.color[k].value), desc: T.primitives.color[k].desc || '', scopes: [], css: cssName('prim-', k),
  })));
  const defs = [];
  for (const k of Object.keys(T.semantic.color)) {
    const d = T.semantic.color[k];
    defs.push({ name: 'color/' + k, type: 'COLOR', value: figma.variables.createVariableAlias(prim['color/' + d.ref]), desc: (d.desc ? d.desc + ' · ' : '') + '= ' + d.ref, scopes: d.scopes, css: cssName('color-', k) });
  }
  for (const k of Object.keys(T.number)) {
    const d = T.number[k];
    defs.push({ name: k, type: 'FLOAT', value: d.value, desc: d.desc || '', scopes: d.scopes, css: cssName('', k) });
  }
  for (const k of Object.keys(T.string)) {
    const d = T.string[k];
    defs.push({ name: k, type: 'STRING', value: d.value, desc: d.desc || '', scopes: d.scopes, css: cssName('', k) });
  }
  const tok = await upsertVariables(await collection(TOKEN_COLLECTION, false), defs);
  return { prim, tok };
}

// ---------------------------------------------------------------- 样式
async function importStyles(V) {
  const text = {};
  for (const d of T.textStyles) {
    const fam = T.string[d.family].value;
    const f = await font(fam, d.style);
    const s = await upsertStyle('text', d.name);
    s.description = d.desc || '';
    s.fontName = f;
    s.fontSize = T.number[d.size].value;
    s.lineHeight = { unit: 'PIXELS', value: d.lineHeight };
    s.letterSpacing = { unit: 'PERCENT', value: d.letterSpacing };
    try { s.setBoundVariable('fontSize', V.tok[d.size]); } catch (e) { warn('文字样式 ' + d.name + ' 绑定字号变量失败：' + e.message); }
    if (f.family === fam) { try { s.setBoundVariable('fontFamily', V.tok[d.family]); } catch (e) { /* 旧版本不支持绑定字体族 */ } }
    text[d.name] = s;
  }
  await pruneStyles('text', T.textStyles.map((d) => STYLE_PREFIX + d.name));

  const effect = {};
  for (const d of T.effectStyles) {
    const s = await upsertStyle('effect', d.name);
    s.description = d.desc || '';
    s.effects = d.effects.map((e) => {
      const c = rgba(T.primitives.color[T.semantic.color[e.color].ref].value);
      const fx = { type: e.type, color: c, offset: { x: e.x, y: e.y }, radius: e.radius, spread: e.spread, visible: true, blendMode: 'NORMAL', showShadowBehindNode: false };
      try { return figma.variables.setBoundVariableForEffect(fx, 'color', V.tok['color/' + e.color]); } catch (err) { return fx; }
    });
    effect[d.name] = s;
  }
  await pruneStyles('effect', T.effectStyles.map((d) => STYLE_PREFIX + d.name));

  const paint = {};
  for (const d of T.paintStyles) {
    const s = await upsertStyle('paint', d.name);
    s.description = d.desc || '';
    if (d.type === 'GRADIENT_RADIAL') {
      // 归一化坐标：中心 (cx, cy)、半径 (rx, ry) → Figma 的 gradientTransform（节点空间 → 渐变空间）
      const cx = d.center[0], cy = d.center[1], rx = d.size[0], ry = d.size[1];
      s.paints = [{ type: 'GRADIENT_RADIAL', gradientTransform: [[1 / (2 * rx), 0, 0.5 - cx / (2 * rx)], [0, 1 / (2 * ry), 0.5 - cy / (2 * ry)]],
        gradientStops: d.stops.map((st) => ({ position: st[1], color: rgba(T.primitives.color[st[0]].value) })) }];
    } else {
      const img = figma.createImage(figma.base64Decode(DATA.images[d.image]));
      const p = { type: 'IMAGE', scaleMode: 'TILE', imageHash: img.hash, scalingFactor: 0.5 };
      if (d.opacity) p.opacity = T.number[d.opacity].value / 100;
      if (d.blend) p.blendMode = d.blend;
      s.paints = [p];
    }
    paint[d.name] = s;
  }
  await pruneStyles('paint', T.paintStyles.map((d) => STYLE_PREFIX + d.name));
  return { text, effect, paint };
}

// ---------------------------------------------------------------- 说明分区
async function buildDocs(V, S) {
  const page = figma.currentPage;
  const old = page.findAll((n) => n.type === 'SECTION' && n.name === SECTION_NAME);
  let x0 = 0, y0 = 0;
  if (old.length) { x0 = old[0].x; y0 = old[0].y; old.forEach((n) => n.remove()); }
  else {
    for (const n of page.children) x0 = Math.max(x0, n.x + n.width);
    if (page.children.length) x0 += 400;
  }
  const C = (k) => V.tok['color/' + k];
  const ts = S.text;

  const root = frame('Foundations', 'VERTICAL', 56);
  root.paddingLeft = root.paddingRight = root.paddingTop = root.paddingBottom = 56;
  root.fills = [boundPaint(C('bg/base'))];
  // resize() 会把自动布局的两个方向都改成固定尺寸，所以要在 resize 之后再把高度设回「随内容」
  root.resize(1440, 100);
  root.counterAxisSizingMode = 'FIXED';
  root.primaryAxisSizingMode = 'AUTO';

  await label(root, T.meta.name, ts['Title/L'], C('text/primary'));
  await label(root, '方向：' + T.meta.direction + '。\n' + T.meta.source + '\n生成自仓库提交 ' + DATA.build.commit + ' · ' + DATA.build.date, ts['Body'], C('text/secondary'), 1100);

  // 颜色
  await label(root, '颜色 · 语义变量（集合「' + TOKEN_COLLECTION + '」；原始色在「' + PRIM_COLLECTION + '」，不直接用）', ts['Heading'], C('text/primary'));
  const grid = frame('Colors', 'HORIZONTAL', 16);
  grid.layoutWrap = 'WRAP';
  grid.counterAxisSpacing = 20;
  root.appendChild(grid);
  grid.layoutSizingHorizontal = 'FILL';
  for (const k of Object.keys(T.semantic.color)) {
    const d = T.semantic.color[k];
    const card = frame(k, 'VERTICAL', 4);
    grid.appendChild(card);
    const sw = figma.createRectangle();
    sw.resize(152, 56);
    sw.fills = [boundPaint(C(k))];
    sw.strokes = [boundPaint(C('line/default'))];
    sw.strokeWeight = 1;
    bindRadius(sw, V.tok['radius/s']);
    card.appendChild(sw);
    await label(card, k, ts['Label'], C('text/primary'), 152);
    await label(card, d.ref + ' · ' + T.primitives.color[d.ref].value, ts['Readout/S'], C('text/secondary'), 152);
    if (d.desc) await label(card, d.desc, ts['Micro'], C('text/secondary'), 152);
  }

  // 对比度
  await label(root, '对比度（构建时校验，不达标就不出插件）', ts['Heading'], C('text/primary'));
  const ctab = frame('Contrast', 'VERTICAL', 6);
  root.appendChild(ctab);
  for (const r of DATA.contrast) await label(ctab, (r[2] >= r[3] ? '✓ ' : '✗ ') + r[2].toFixed(2) + ':1 ≥ ' + r[3] + '   ' + r[0] + ' on ' + r[1] + '   · ' + r[4], ts['Caption'], C(r[2] >= r[3] ? 'text/primary' : 'feedback/danger'));

  // 文字
  await label(root, '文字样式（数字 Barlow Condensed · 中文 Noto Sans SC · 刻度读数 JetBrains Mono；字号下限 ' + T.number['font-size/min'].value + '）', ts['Heading'], C('text/primary'));
  const sample = { Number: '13,854', Readout: '8 · 16 · 22 · 1:35' }; // JetBrains Mono 没有中文字形，样例只放数字
  for (const d of T.textStyles) {
    const row = frame(d.name, 'HORIZONTAL', 24);
    row.counterAxisAlignItems = 'CENTER';
    root.appendChild(row);
    await label(row, d.name + '\n' + T.string[d.family].value + ' ' + d.style + ' ' + T.number[d.size].value + '/' + d.lineHeight, ts['Readout/S'], C('text/secondary'), 220);
    await label(row, sample[d.name.split('/')[0]] || '今天练 7 块肌肉 · 14 组 · 中下胸 恢复 3%', ts[d.name], C('text/primary'));
  }

  // 圆角、间距、描边
  await label(root, '圆角 · 间距 · 描边', ts['Heading'], C('text/primary'));
  const shapes = frame('Radius', 'HORIZONTAL', 24);
  root.appendChild(shapes);
  for (const k of Object.keys(T.number).filter((n) => n.indexOf('radius/') === 0)) {
    const cell = frame(k, 'VERTICAL', 6);
    shapes.appendChild(cell);
    const r = figma.createRectangle();
    r.resize(96, 56);
    r.fills = [boundPaint(C('bg/raised'))];
    r.strokes = [boundPaint(C('line/strong'))];
    r.strokeWeight = 1;
    bindRadius(r, V.tok[k]);
    cell.appendChild(r);
    await label(cell, k + ' · ' + T.number[k].value, ts['Readout/S'], C('text/secondary'));
  }
  const spaces = frame('Spacing', 'VERTICAL', 8);
  root.appendChild(spaces);
  for (const k of Object.keys(T.number).filter((n) => n.indexOf('space/') === 0)) {
    const row = frame(k, 'HORIZONTAL', 12);
    row.counterAxisAlignItems = 'CENTER';
    spaces.appendChild(row);
    await label(row, k, ts['Readout/S'], C('text/secondary'), 90);
    const bar = figma.createRectangle();
    bar.resize(T.number[k].value, 12);
    bar.setBoundVariable('width', V.tok[k]);
    bar.fills = [boundPaint(C('accent/default'))];
    row.appendChild(bar);
    await label(row, String(T.number[k].value), ts['Readout/S'], C('text/secondary'));
  }

  // 效果、填充、容量四档
  await label(root, '效果与填充样式 · 容量四档（明暗 + 纹理，不只靠色相）', ts['Heading'], C('text/primary'));
  const fx = frame('Effects', 'HORIZONTAL', 32);
  fx.paddingTop = fx.paddingBottom = 24;
  root.appendChild(fx);
  async function chip(name, w, h, apply) {
    const cell = frame(name, 'VERTICAL', 10);
    fx.appendChild(cell);
    const r = figma.createRectangle();
    r.resize(w, h);
    bindRadius(r, V.tok['radius/l']);
    r.fills = [boundPaint(C('bg/raised'))];
    await apply(r);
    cell.appendChild(r);
    await label(cell, name, ts['Micro'], C('text/secondary'), Math.max(w, 120));
  }
  for (const d of T.effectStyles) await chip('Milo/' + d.name, 140, 72, (r) => r.setEffectStyleIdAsync(S.effect[d.name].id));
  for (const d of T.paintStyles) await chip('Milo/' + d.name, d.name === 'Hero/Lime' ? 200 : 120, 72, async (r) => {
    if (d.name === 'Texture/Grain') r.fills = [boundPaint(C('accent/default'))].concat(S.paint[d.name].paints);
    else await r.setFillStyleIdAsync(S.paint[d.name].id);
  });
  const tiers = [['未练', (r) => { r.fills = [boundPaint(C('data/tier-none'))]; r.strokes = [boundPaint(C('data/tier-none-edge'))]; r.strokeWeight = 1; }],
    ['不足', (r) => r.setFillStyleIdAsync(S.paint['Data/Tier-Low'].id)],
    ['达标', (r) => { r.fills = [boundPaint(C('data/tier-ok'))]; }],
    ['超量', (r) => r.setFillStyleIdAsync(S.paint['Data/Tier-Over'].id)]];
  for (const t of tiers) await chip('容量 · ' + t[0], 72, 40, async (r) => { bindRadius(r, V.tok['radius/pill']); await t[1](r); });

  // 规则摘要
  await label(root, '使用规则（全文见仓库 docs/DESIGN.md）', ts['Heading'], C('text/primary'));
  await label(root, [
    '1. 荧光色只给三类：当前主角（放大的胶囊、今日处方卡）、导航选中项、进度。正文、图标、分割线、按钮一律不用。',
    '2. 光晕（Glow/Focus）每屏最多一处；导航选中项是实心填充，不发光。',
    '3. 「超量」用白底黑斜纹，绝不用荧光；错误只用 feedback/danger。',
    '4. 主按钮是暖白（action/primary），不是荧光。',
    '5. 页面里只用变量和样式，不写散落的数值；改值改仓库 tokens.json 再重跑插件。',
  ].join('\n'), ts['Body'], C('text/secondary'), 1200);

  const section = figma.createSection();
  section.name = SECTION_NAME;
  section.x = x0;
  section.y = y0;
  section.appendChild(root);
  root.x = 40;
  root.y = 40;
  section.resizeWithoutConstraints(root.width + 80, root.height + 80);
  figma.viewport.scrollAndZoomIntoView([section]);
  return section;
}


/* 组件：分区「Components · 配重片」。按名字幂等——已有的组件集与变体保留节点 ID、只重建内部，已放出去的实例不会断。
 * 组件只服务标杆页 P06 与导航；P01 等页面的组件到阶段 6 做到那页时再加。 */

// ---------------------------------------------------------------- 小工具
const TOK = (V, k) => V.tok[k];
const COL = (V, k) => V.tok['color/' + k];
const fill = (V, k, opacity) => [boundPaint(COL(V, k), opacity)];
const hexOf = (k) => T.primitives.color[T.semantic.color[k].ref].value;
const r1 = (x) => String(Math.round(x * 10) / 10);
const HEAD_RANGES = { large: [8, 16, 22], medium: [7, 13, 18], small: [5, 10, 14] }; // 最低 / 适宜 / 上限，ia §1.10 按肌头大小缩放
const TIER_CN = { large: '大', medium: '中', small: '小' };

function rect(parent, name, w, h, paints) {
  const r = figma.createRectangle();
  r.name = name;
  r.resize(Math.max(0.01, w), Math.max(0.01, h));
  r.fills = paints || [];
  parent.appendChild(r);
  return r;
}
function ellipse(parent, name, d, paints) {
  const e = figma.createEllipse();
  e.name = name;
  e.resize(d, d);
  e.fills = paints || [];
  parent.appendChild(e);
  return e;
}
// 折线矢量：坐标先归一化到自身原点，再把节点挪到最小点，避免依赖 Figma 对路径偏移的处理方式
function polyline(parent, name, pts, closed) {
  const minX = Math.min.apply(null, pts.map((p) => p[0])), minY = Math.min.apply(null, pts.map((p) => p[1]));
  const f = (n) => (Math.round(n * 100) / 100).toString();
  const data = pts.map((p, i) => (i ? 'L ' : 'M ') + f(p[0] - minX) + ' ' + f(p[1] - minY)).join(' ') + (closed ? ' Z' : '');
  const v = figma.createVector();
  v.name = name;
  v.vectorPaths = [{ windingRule: 'NONE', data: data }];
  v.fills = [];
  parent.appendChild(v);
  v.x = minX;
  v.y = minY;
  return v;
}
function stroke(V, node, colorKey, weightKey, opacity) {
  node.strokes = [boundPaint(COL(V, colorKey), opacity)];
  node.strokeWeight = T.number[weightKey].value;
  try { node.setBoundVariable('strokeWeight', TOK(V, weightKey)); } catch (e) { /* 旧版本不能绑定描边宽度 */ }
}
// 胶囊轮廓上的点：从顶边正中出发、顺时针，走过 frac 比例的周长
function pillPoints(x, y, w, h, frac, n) {
  const r = h / 2, sx = w - 2 * r, L = 2 * sx + 2 * Math.PI * r;
  const at = (s) => {
    if (s <= sx / 2) return [x + w / 2 + s, y];
    s -= sx / 2;
    if (s <= Math.PI * r) { const a = -Math.PI / 2 + s / r; return [x + w - r + r * Math.cos(a), y + r + r * Math.sin(a)]; }
    s -= Math.PI * r;
    if (s <= sx) return [x + w - r - s, y + h];
    s -= sx;
    if (s <= Math.PI * r) { const a = Math.PI / 2 + s / r; return [x + r + r * Math.cos(a), y + r + r * Math.sin(a)]; }
    s -= Math.PI * r;
    return [x + r + s, y];
  };
  const N = Math.max(2, Math.ceil((n || 180) * frac));
  const pts = [];
  for (let i = 0; i <= N; i++) pts.push(at((i / N) * frac * L));
  return pts;
}
// 刻度条的已填部分：硬边线性渐变（在实例里覆盖 fills 即可改比例，不用改尺寸）
function hardFill(colorKey, frac, opacity) {
  const c = rgba(hexOf(colorKey));
  const a = opacity == null ? 1 : opacity;
  const f = Math.max(0, Math.min(1, frac));
  return { type: 'GRADIENT_LINEAR', gradientTransform: [[1, 0, 0], [0, 1, 0]], gradientStops: [
    { position: 0, color: { r: c.r, g: c.g, b: c.b, a: a } }, { position: f, color: { r: c.r, g: c.g, b: c.b, a: a } },
    { position: Math.min(1, f + 0.0001), color: { r: c.r, g: c.g, b: c.b, a: 0 } }, { position: 1, color: { r: c.r, g: c.g, b: c.b, a: 0 } }] };
}
async function txt(parent, name, chars, styleName, S, V, colorKey, opacity) {
  const t = await label(parent, chars, S.text[styleName], COL(V, colorKey));
  t.name = name;
  if (opacity != null) t.fills = [boundPaint(COL(V, colorKey), opacity)];
  return t;
}
function auto(parent, name, dir, gap, pad) {
  const f = frame(name, dir, gap);
  if (pad) { f.paddingTop = pad[0]; f.paddingRight = pad[1]; f.paddingBottom = pad[2]; f.paddingLeft = pad[3]; }
  if (parent) parent.appendChild(f);
  return f;
}
async function svgNode(parent, name, svg) {
  const n = figma.createNodeFromSvg(svg);
  n.name = name;
  n.fills = [];
  n.clipsContent = false;
  parent.appendChild(n);
  return n;
}
async function resetComponent(c) {
  for (const ch of c.children.slice()) ch.remove();
  c.layoutMode = 'NONE';
  c.fills = [];
  c.strokes = [];
  c.effects = [];
  c.clipsContent = false;
  await c.setEffectStyleIdAsync('');
  await c.setFillStyleIdAsync('');
}

// ---------------------------------------------------------------- 组件集（幂等）
function combos(axes) {
  let out = [{}];
  for (const [k, vals] of axes) {
    const next = [];
    for (const o of out) for (const v of vals) { const n = Object.assign({}, o); n[k] = v; next.push(n); }
    out = next;
  }
  return out;
}
const variantName = (p) => Object.keys(p).map((k) => k + '=' + p[k]).join(', ');

async function upsertSet(sec, name, desc, axes, build, skip) {
  let set = sec.findChild((n) => n.type === 'COMPONENT_SET' && n.name === name);
  const keep = [], fresh = [];
  for (const props of combos(axes).filter((q) => !(skip && skip(q)))) {
    const vname = variantName(props);
    let comp = set ? set.findChild((c) => c.type === 'COMPONENT' && c.name === vname) : null;
    if (comp) { await resetComponent(comp); report.updated++; }
    else { comp = figma.createComponent(); comp.name = vname; report.created++; if (set) set.appendChild(comp); else fresh.push(comp); }
    await build(comp, props);
    keep.push(comp.id);
  }
  if (!set) { set = figma.combineAsVariants(fresh, sec); set.name = name; }
  else if (fresh.length) warn('不该出现：新变体没有挂到组件集上');
  for (const c of set.children.slice()) if (keep.indexOf(c.id) < 0) { warn('组件 ' + name + ' 的变体「' + c.name + '」仓库里已没有，已移除'); c.remove(); report.removed++; }
  set.description = desc;
  set.fills = [];
  set.layoutMode = 'HORIZONTAL';
  set.layoutWrap = 'WRAP';
  set.itemSpacing = 24;
  set.counterAxisSpacing = 24;
  set.paddingLeft = set.paddingRight = set.paddingTop = set.paddingBottom = 24;
  set.resize(1400, 100);
  set.primaryAxisSizingMode = 'FIXED';
  set.counterAxisSizingMode = 'AUTO';
  return set;
}
async function upsertComp(sec, name, desc, build) {
  let comp = sec.findChild((n) => n.type === 'COMPONENT' && n.name === name);
  if (comp) { await resetComponent(comp); report.updated++; } else { comp = figma.createComponent(); comp.name = name; sec.appendChild(comp); report.created++; }
  await build(comp);
  comp.description = desc;
  return comp;
}
function variant(set, props) {
  const c = set.findChild((n) => n.type === 'COMPONENT' && n.name === variantName(props));
  if (!c) throw new Error('找不到变体 ' + set.name + ' / ' + variantName(props));
  return c;
}
function findSection(name) {
  return figma.currentPage.findAll((n) => n.type === 'SECTION' && n.name === name)[0] || null;
}
function placeRight() {
  let x = 0;
  for (const n of figma.currentPage.children) x = Math.max(x, n.x + n.width);
  return figma.currentPage.children.length ? x + 400 : 0;
}

// ---------------------------------------------------------------- 各组件
async function buildScaleBar(c, p, V, S) {
  const panel = p.size === '面板', onAcc = p.tone === '荧光底';
  const W = panel ? 296 : 150, H = panel ? 34 : 4, by = panel ? 4 : 1, bh = panel ? 10 : 2;
  c.resize(W, H);
  const ranges = HEAD_RANGES[{ 大: 'large', 中: 'medium', 小: 'small' }[p.tier]];
  const sc = ranges[2] * (panel ? 1.15 : 1.1);
  const ink = onAcc ? 'text/on-accent' : 'data/fill';
  const track = rect(c, 'track', W, bh, onAcc ? fill(V, 'text/on-accent', 0.2) : fill(V, 'data/track'));
  track.y = by;
  bindRadius(track, TOK(V, 'radius/xs'));
  const fl = rect(c, 'fill', W, bh, [hardFill(ink, 0.45)]);
  fl.y = by;
  bindRadius(fl, TOK(V, 'radius/xs'));
  const names = ['最低', '适宜', '上限'], keys = ['mev', 'mav', 'mrv'];
  for (let i = 0; i < 3; i++) {
    const x = (W * ranges[i]) / sc;
    const t = rect(c, 'tick/' + keys[i], 1.5, panel ? 18 : 4, onAcc ? fill(V, 'text/on-accent') : fill(V, 'data/tick'));
    t.x = x - 0.75;
    t.y = 0;
    if (panel) {
      const l = await txt(c, 'lb/' + keys[i], names[i] + ' ' + ranges[i], 'Micro', S, V, 'text/secondary');
      l.x = Math.min(W - l.width, Math.max(0, x - l.width / 2));
      l.y = 20;
    }
  }
  for (const ch of c.children) ch.constraints = { horizontal: 'SCALE', vertical: 'MIN' };
}

async function buildCapsule(c, p, V, S, K) {
  const st = p.state, center = st === '放大中心', near = st === '邻近放大', dead = st === '未练';
  const W = T.number['size/capsule-w'].value + (center ? T.number['size/capsule-mag-w'].value : near ? 13 : 0);
  c.layoutMode = 'VERTICAL';
  c.itemSpacing = center ? 4 : near ? 2 : 1;
  const pv = center ? 9 : near ? 5 : 3, ph = center ? 14 : near ? 12 : 10;
  c.paddingTop = c.paddingBottom = pv;
  c.paddingLeft = ph;
  c.paddingRight = ph - 2;
  c.resize(W, T.number['size/capsule-h'].value);
  c.counterAxisSizingMode = 'FIXED';
  c.primaryAxisSizingMode = 'AUTO';
  bindRadius(c, TOK(V, 'radius/pill'));
  if (dead) { c.fills = fill(V, 'bg/raised'); await c.setFillStyleIdAsync(S.paint['Data/Untrained'].id); }
  else c.fills = fill(V, center ? 'accent/default' : 'bg/raised');
  if (center) await c.setEffectStyleIdAsync(S.effect['Glow/Focus'].id);
  if (st === '选中') stroke(V, c, 'accent/default', 'stroke/focus');
  const ink = center ? 'text/on-accent' : dead ? 'text/secondary' : 'text/primary';
  const ink2 = center ? 'text/on-accent-secondary' : 'text/secondary';
  const row = auto(c, 'row', 'HORIZONTAL', 6);
  row.layoutSizingHorizontal = 'FILL';
  row.primaryAxisAlignItems = 'SPACE_BETWEEN';
  row.counterAxisAlignItems = 'CENTER';
  await txt(row, 'name', '中下胸', center ? 'Body/Strong' : near ? 'Label' : 'Micro', S, V, ink);
  const nums = auto(row, 'nums', 'HORIZONTAL', 1);
  nums.counterAxisAlignItems = 'MAX';
  await txt(nums, 'num', '7.5', center ? 'Number/M' : near ? 'Number/S' : 'Number/XS', S, V, ink);
  await txt(nums, 'den', '/16', 'Caption', S, V, ink2);
  if (center || near) await txt(c, 'sub', '恢复 3% · 修复期', 'Caption', S, V, ink2);
  const bar = variant(K.ScaleBar, { size: '胶囊', tone: center ? '荧光底' : '默认', tier: '大' }).createInstance();
  bar.name = 'bar';
  c.appendChild(bar);
  bar.layoutSizingHorizontal = 'FILL';
}

async function buildNavPill(c, p, V, S) {
  const O = 3, W = T.number['size/nav-w'].value, H = T.number['size/nav-h'].value;
  const PW = T.number['size/nav-pill-w'].value, SW = (W - 12 - PW) / 2, PH = T.number['size/nav-pill-h'].value, PAD = 6;
  const sel = ['今日', '进度', '设置'].indexOf(p.selected);
  const prog = { 无环: null, 进度: 0.57, 休息: null, '进度+休息': 0.57, 满环: 1 }[p.ring];
  const rest = p.ring === '休息' || p.ring === '进度+休息' ? 0.53 : null;
  c.resize(W + 2 * O, H + 2 * O);
  const shell = rect(c, 'shell', W, H, fill(V, 'nav/bg'));
  shell.x = O; shell.y = O;
  bindRadius(shell, TOK(V, 'radius/pill'));
  await shell.setEffectStyleIdAsync(S.effect['Elevation/Float'].id);
  const xs = [], ws = [];
  let x = PAD;
  for (let i = 0; i < 3; i++) { const w = i === sel ? PW : SW; xs.push(x); ws.push(w); x += w; }
  const k = p.state === '按下' ? 0.96 : 1;
  const pill = rect(c, 'pill', ws[sel] * k, PH * k, fill(V, 'nav/pill'));
  pill.x = O + xs[sel] + (ws[sel] * (1 - k)) / 2;
  pill.y = O + PAD + (PH * (1 - k)) / 2;
  bindRadius(pill, TOK(V, 'radius/pill'));
  const names = ['今日', '进度', '设置'], icons = ['today', 'progress', 'settings'];
  for (let i = 0; i < 3; i++) {
    const on = i === sel;
    const item = auto(c, 'item/' + names[i], 'HORIZONTAL', 6);
    item.primaryAxisAlignItems = 'CENTER';
    item.counterAxisAlignItems = 'CENTER';
    item.resize(ws[i], PH);
    item.primaryAxisSizingMode = 'FIXED';
    item.counterAxisSizingMode = 'FIXED';
    item.x = O + xs[i];
    item.y = O + PAD;
    const ic = await svgNode(item, 'icon', DATA.icons[icons[i]]);
    ic.rescale(20 / ic.width);
    for (const v of ic.findAll((n) => n.type === 'VECTOR')) { v.fills = fill(V, on ? 'nav/pill-ink' : 'nav/ink'); v.strokes = []; }
    if (on) {
      await txt(item, 'label', names[i], 'Label', S, V, 'nav/pill-ink');
      if (rest != null) await txt(item, 'time', '1:35', 'Readout/M', S, V, 'nav/pill-ink');
    }
  }
  // 外圈：今日进度（实线，从顶边正中顺时针）
  if (prog != null) {
    const track = polyline(c, 'ring/track', pillPoints(O - 1.5, O - 1.5, W + 3, H + 3, 1, 180), true);
    stroke(V, track, 'nav/track', 'stroke/ring-track');
    if (prog > 0) {
      const pr = polyline(c, 'ring/progress', pillPoints(O - 1.5, O - 1.5, W + 3, H + 3, prog, 180), prog >= 1);
      stroke(V, pr, 'nav/progress', 'stroke/ring-progress');
      pr.strokeCap = 'ROUND';
    }
  }
  // 小胶囊：休息倒计时（虚线 + 端点圆点，与胶囊之间留缝）
  if (rest != null) {
    const G = T.number['stroke/ring-gap'].value;
    const pts = pillPoints(O + xs[sel] - G, O + PAD - G, ws[sel] + 2 * G, PH + 2 * G, rest, 140);
    const rs = polyline(c, 'ring/rest', pts, false);
    stroke(V, rs, 'nav/rest', 'stroke/ring-rest');
    rs.dashPattern = [T.number['stroke/ring-rest-dash'].value, T.number['stroke/ring-rest-gapdash'].value];
    rs.strokeCap = 'ROUND';
    const d = 2 * (T.number['stroke/ring-rest'].value + 1.3);
    const dot = ellipse(c, 'ring/rest-dot', d, fill(V, 'nav/rest'));
    dot.x = pts[pts.length - 1][0] - d / 2;
    dot.y = pts[pts.length - 1][1] - d / 2;
  }
}

async function buildSegmented(c, p, V, S) {
  const n = Number(p.items), sel = Number(p.selected) - 1;
  const labels = n === 3 ? ['容量与恢复', '训练记录', '动作进步'] : ['正面', '背面'];
  c.layoutMode = 'HORIZONTAL';
  c.itemSpacing = 0;
  c.paddingLeft = c.paddingRight = c.paddingTop = c.paddingBottom = 3;
  c.fills = fill(V, 'bg/raised');
  bindRadius(c, TOK(V, 'radius/pill'));
  if (n === 3) { c.resize(328, 40); c.primaryAxisSizingMode = 'FIXED'; c.counterAxisSizingMode = 'AUTO'; }
  for (let i = 0; i < n; i++) {
    const it = auto(c, 'item/' + (i + 1), 'HORIZONTAL', 0, n === 3 ? [8, 10, 8, 10] : [5, 12, 5, 12]);
    it.primaryAxisAlignItems = 'CENTER';
    bindRadius(it, TOK(V, 'radius/pill'));
    if (i === sel) it.fills = fill(V, 'control/selected');
    if (n === 3) it.layoutGrow = 1;
    await txt(it, 'label', labels[i], n === 3 ? 'Label' : 'Caption', S, V, i === sel ? 'control/selected-ink' : 'text/secondary');
  }
}

async function buildButton(c, p, V, S) {
  const main = p.kind === '主';
  c.layoutMode = 'HORIZONTAL';
  c.primaryAxisAlignItems = 'CENTER';
  c.counterAxisAlignItems = 'CENTER';
  c.paddingLeft = c.paddingRight = 24;
  c.resize(160, T.number[p.size === 'L' ? 'size/button-h' : 'size/button-h-s'].value);
  c.primaryAxisSizingMode = 'FIXED';
  c.counterAxisSizingMode = 'FIXED';
  try { c.setBoundVariable('height', TOK(V, p.size === 'L' ? 'size/button-h' : 'size/button-h-s')); } catch (e) { /* 可选 */ }
  bindRadius(c, TOK(V, 'radius/pill'));
  if (main) c.fills = fill(V, 'action/primary'); else stroke(V, c, 'line/default', 'stroke/hairline');
  await txt(c, 'label', main ? '关闭' : '展开更多', 'Body/Strong', S, V, main ? 'action/primary-ink' : 'text/primary');
}

async function buildRecovery(c, p, V, S) {
  await blockFrame(c, V);
  const top = await blockTop(c, V, S, '恢复度', '3', '%', p.phase, '还需约 70 小时 · 本次窗口 61 小时');
  const segs = [['修复期', 0.5], ['恢复中', 0.5], ['黄金窗', 1], ['已回落', 0.6]], total = 2.6, W = 300 - 9;
  const bar = auto(c, 'phases', 'HORIZONTAL', 3);
  const lbs = auto(c, 'phase-labels', 'HORIZONTAL', 3);
  for (const s of segs) {
    const w = (W * s[1]) / total, on = s[0] === p.phase;
    const r = rect(bar, 'phase/' + s[0], w, 8, fill(V, on ? 'accent/default' : 'data/track'));
    bindRadius(r, TOK(V, 'radius/xs'));
    const l = await txt(lbs, 'lb/' + s[0], s[0], 'Micro', S, V, on ? 'text/primary' : 'text/secondary');
    l.textAutoResize = 'HEIGHT';
    l.resize(w, l.height);
    l.textAutoResize = 'HEIGHT';
  }
  return top;
}
async function buildVolume(c, p, V, S, K) {
  await blockFrame(c, V);
  await blockTop(c, V, S, '近 7 天', '7.5', '组', '低于最低有效量', '还差 0.5 组到最低有效量');
  const bar = variant(K.ScaleBar, { size: '面板', tone: '默认', tier: p.tier }).createInstance();
  bar.name = 'bar';
  c.appendChild(bar);
}
async function blockFrame(c, V) {
  c.layoutMode = 'VERTICAL';
  c.itemSpacing = 10;
  c.paddingLeft = c.paddingRight = c.paddingTop = c.paddingBottom = 14;
  c.resize(328, 100);
  c.counterAxisSizingMode = 'FIXED';
  c.primaryAxisSizingMode = 'AUTO';
  c.fills = fill(V, 'bg/raised');
  bindRadius(c, TOK(V, 'radius/l'));
}
async function blockTop(c, V, S, k, big, unit, ph, sub) {
  const row = auto(c, 'top', 'HORIZONTAL', 8);
  row.layoutSizingHorizontal = 'FILL';
  row.primaryAxisAlignItems = 'SPACE_BETWEEN';
  row.counterAxisAlignItems = 'MAX';
  const left = auto(row, 'left', 'VERTICAL', 2);
  await txt(left, 'k', k, 'Caption', S, V, 'text/secondary');
  const nums = auto(left, 'nums', 'HORIZONTAL', 3);
  nums.counterAxisAlignItems = 'MAX';
  await txt(nums, 'big', big, 'Number/XL', S, V, 'text/primary');
  await txt(nums, 'unit', unit, 'Body/Strong', S, V, 'text/secondary');
  const right = auto(row, 'right', 'VERTICAL', 2);
  right.counterAxisAlignItems = 'MAX';
  await txt(right, 'ph', ph, 'Body/Strong', S, V, 'text/primary');
  await txt(right, 'sub', sub, 'Caption', S, V, 'text/secondary');
  return row;
}

async function buildBody(c, p, V, S) {
  const g = p.gender === '男' ? 'male' : 'female', view = p.view === '正面' ? 'front' : 'back';
  const art = await svgNode(c, 'art', DATA.bodymap[g][view]);
  art.rescale(176 / art.width);
  c.resize(art.width, art.height);
  art.x = 0; art.y = 0;
  for (const grp of art.children) {
    const vecs = grp.findAll((n) => n.type === 'VECTOR' || n.type === 'LINE');
    if (grp.name === 'neutral') vecs.forEach((v) => { v.fills = fill(V, 'data/body'); stroke(V, v, 'line/strong', 'stroke/hairline'); v.strokeWeight = 0.6; });
    else if (grp.name === 'contour') { grp.opacity = 0.5; vecs.forEach((v) => { if (v.type === 'VECTOR') v.fills = []; stroke(V, v, 'line/strong', 'stroke/hairline'); }); }
    else if (grp.name.indexOf('muscle--') === 0) {
      grp.name = 'muscle/' + grp.name.slice(8);
      vecs.forEach((v) => { v.fills = fill(V, 'data/tier-none'); stroke(V, v, 'data/tier-none-edge', 'stroke/hairline'); v.strokeWeight = 0.6; });
    }
  }
  if (!art.findAll((n) => n.name.indexOf('muscle/') === 0).length) warn('人体图导入后没找到任何 muscle/ 图层：Figma 没有用 SVG 的 id 命名图层，肌肉着色会失效');
}

async function buildLegend(c, V, S) {
  c.layoutMode = 'HORIZONTAL';
  c.itemSpacing = 10;
  c.counterAxisAlignItems = 'CENTER';
  const tiers = [['未练', 'none'], ['不足', 'low'], ['达标', 'ok'], ['超量', 'over']];
  for (const t of tiers) {
    const it = auto(c, 'tier/' + t[1], 'HORIZONTAL', 4);
    it.counterAxisAlignItems = 'CENTER';
    const chip = rect(it, 'chip', 16, 8, fill(V, 'data/tier-none'));
    bindRadius(chip, TOK(V, 'radius/pill'));
    if (t[1] === 'none') stroke(V, chip, 'data/tier-none-edge', 'stroke/hairline');
    if (t[1] === 'low') await chip.setFillStyleIdAsync(S.paint['Data/Tier-Low'].id);
    if (t[1] === 'ok') chip.fills = fill(V, 'data/tier-ok');
    if (t[1] === 'over') await chip.setFillStyleIdAsync(S.paint['Data/Tier-Over'].id);
    await txt(it, 'label', t[0], 'Micro', S, V, 'text/secondary');
  }
}

